// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum) public {
        vm.assume(blockNum > 0);
        vm.roll(blockNum);
        vm.warp(1000);
        address caller = address(0x1234);
        vm.deal(caller, 20 ether);
        vm.prank(caller);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2);
    }
}
